<template><article class="panel pollutant-chart"><div class="panel-title"><div><h2>省分组污染物超标累计</h2><p>SO2、CO、PM2.5及最终AQI超标数量对比</p></div><div class="pollutant-legend"><span v-for="item in series" :key="item.key"><i :style="{background:item.color}"></i>{{item.label}}</span></div></div><div class="pollutant-axis"><span>省份</span><span>0</span><span>{{Math.ceil(max/2)}}</span><span>{{max}}</span></div><div class="pollutant-rows"><div v-for="row in displayRows" :key="row.province"><strong>{{row.province}}</strong><section><div v-for="item in series" :key="item.key" :title="`${item.label}：${row[item.key]}条`"><i :style="{width:barWidth(row[item.key]),background:item.color}"></i><b>{{row[item.key]}}</b></div></section></div></div></article></template>
<script setup>
import{computed}from'vue';const props=defineProps({rows:{type:Array,default:()=>[]}});const series=[{key:'so2',label:'SO2',color:'#2588ad'},{key:'co',label:'CO',color:'#e49b32'},{key:'pm25',label:'PM2.5',color:'#dc6650'},{key:'aqi',label:'AQI',color:'#168f6b'}];const displayRows=computed(()=>props.rows.slice().sort((a,b)=>b.aqi-a.aqi).slice(0,10));const max=computed(()=>Math.max(1,...props.rows.flatMap(row=>series.map(item=>Number(row[item.key]||0)))));const barWidth=value=>`${Math.max(value?8:0,Number(value||0)/max.value*100)}%`
</script>
